  "frozen_questions": [
    {
      "gap": "种子在果核内，钻核才能使人无法获得种子，但文中未说明这一物理关系。",
      "question_id": "Q1",
      "story_span": "恒鑚其核"
    },
    {
      "gap": "担心别人获得种子是怕别人种出同样好李而竞争，但动机未明示。",
      "question_id": "Q2",
      "story_span": "恐人得其種"
    },
    {
      "gap": "钻核必须发生在出售前，否则顾客已取得核，行动無意义，但时间顺序未说明。",
      "question_id": "Q3",
      "story_span": "賣之恐人得其種恒鑚其核"
    }
  ],
  "later_commentary": {
    "label": "余嘉錫箋疏",
    "notes": []
  },
  "primary_text": {
    "label": "世說新語正文",
    "text": "王戎有好李賣之恐人得其種恒鑚其核"
  },
